#!/usr/bin/env python3
"""immuno/car_target_screen — auto-generated run.py (archetype=mhc_epitope).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "mhc_epitope"
BRAIN = "immuno"
SKILL = "car_target_screen"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'targets': [{'gene': 'CD33', 'tumor_expression_pct': 0.92, 'normal_essential_max_TPM': 0.4, 'surface_localization_confidence': 0.91, 'differential_expression_ratio': 18.5, 'escape_risk_score': 0.32, 'on_target_off_tumor_risk': 'low', 'recommended_affinity_kd_nm': 35}]})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """CAR target screen:基于 target gene 在 normal tissue vs tumor 表达(用户提供)+ surface-only 过滤。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    targets = payload.get("candidate_targets") or []
    tumor_expr = payload.get("tumor_expression_csv")  # gene,mean
    normal_expr = payload.get("normal_expression_csv")  # gene,tissue,mean
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "n_candidates": len(targets)}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_epitopes": 0, "epitopes_csv": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not targets:
        return {"ok": False, "error": "需要 candidate_targets", "diagnostics": diagnostics}
    if not tumor_expr or not _os.path.isfile(tumor_expr):
        return {"ok": False, "error": "需要 tumor_expression_csv", "diagnostics": diagnostics}
    script = (
        "import json, sys, pandas as pd\n"
        f"targets = {targets!r}; tum = pd.read_csv({tumor_expr!r})\n"
        f"norm_path = {normal_expr!r}\n"
        "norm = pd.read_csv(norm_path) if norm_path else None\n"
        "results = []\n"
        "for t in targets:\n"
        "    tm = tum[tum['gene'] == t]['mean'].values\n"
        "    tm_v = float(tm[0]) if len(tm) else 0.0\n"
        "    nm_max = 0.0\n"
        "    if norm is not None:\n"
        "        nm = norm[norm['gene'] == t]['mean']\n"
        "        nm_max = float(nm.max()) if len(nm) else 0.0\n"
        "    ratio = tm_v / (nm_max + 1e-6)\n"
        "    results.append({'target': t, 'tumor_mean': tm_v, 'normal_max': nm_max,\n"
        "                   'tumor_to_normal_ratio': ratio,\n"
        "                   'pass_specificity': ratio > 5.0})\n"
        "results.sort(key=lambda x: -x['tumor_to_normal_ratio'])\n"
        "json.dump({'n_candidates': len(results), 'results': results,\n"
        "           'n_pass_specificity': sum(1 for r in results if r['pass_specificity'])}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=120)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "screen 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL,
            "n_epitopes": parsed.get("n_candidates", 0),
            "epitopes_csv": "",
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, **parsed}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
